  parameter bit BYPASS_MAC=0, BYPASS_SEQUENCE=0, BYPASS_EPOCH=0,
  parameter int NI_SLOT_TIMEOUT=0   // I-9 (M-F1 rev 8 sec. 6)
)(
  input logic clk,rst,
  input logic [79:0] boot_epoch,
  input logic tx_valid,
  output logic tx_ready,
  input noc_pkg::coord_t tx_dest_coord,
  input noc_pkg::msg_type_e tx_msg_type,
  input logic [10:0] tx_control,
  input logic [31:0] tx_payload_data,
  input logic tx_payload_valid,
  output logic tx_payload_ready,
  output logic tx_error,
  output noc_pkg::flit_t noc_tx_flit,
  output logic noc_tx_valid,
  input logic noc_tx_ready,
  input noc_pkg::flit_t noc_rx_flit,
  input logic noc_rx_valid,
  output logic noc_rx_ready,
  output noc_pkg::coord_t rx_src_coord,rx_dest_coord,
  output noc_pkg::msg_type_e rx_msg_type,
  output logic [10:0] rx_control,
  output logic [4:0] rx_length,
  output logic rx_head_valid,
  output logic [31:0] rx_payload_data,
  output logic rx_payload_valid,rx_payload_last,
  input logic rx_ready,
  output logic rx_abort,
  output logic [31:0] rejected_count,accepted_count,p_slot_drops,
  output logic [3:0] reject_reason,
  output logic tx_busy,rx_busy,
  // contract sec. 4 accounting: at quiescence peer_accepted == peer_replayed + peer_rejected; peer_hold_max is the longest
  // D2 hold (consecutive cycles with a peer HEAD held), asserted <= H_MAX = 512
  output logic [31:0] peer_accepted,peer_replayed,peer_rejected,
  output logic [15:0] peer_hold_max,
  // shared engine (l2_kmac_engine)
  output logic tx_req,rx_req,
  output logic [31:0] tx_wd,rx_wd,
  output logic [6:0] tx_mlen,rx_mlen,
  input logic e_grant,
  input logic [1:0] e_grant_id,e_owner,
  input logic [4:0] e_widx,
  input logic e_done,
  input logic [127:0] e_tag
);
  import noc_pkg::*;
  import noc_p7_pkg::*;
  localparam int MAX_WIRE=26, T_RL=64;
  typedef enum logic [3:0] {T_IDLE,T_FILL,T_PREP,T_REQ,T_WAIT,T_ISSUE,T_NIFILL,T_SEND} ts_t;
  ts_t ts;
  logic [31:0] tp[16];                 // TX payload, LUTRAM (written only in T_FILL)
  logic [4:0] pn,fill,send_fill;
  logic [63:0] tx_seq,rx_seq,seq_q;
  logic [79:0] epoch_q;
  coord_t dest_q;
  msg_type_e msg_q;
  logic [10:0] ctl_q;
  head_flit_t preview,head_q;
  logic [127:0] tx_tag_q;
  logic ni_tv,ni_tr,ni_pv,ni_pr,ni_error,ni_tb,ni_rb;
  flit_t ni_nf;
  logic ni_nv,ni_nr;
  int extension;
  logic [159:0] freshness;
  logic [255:0] tx_hdr;
  function automatic int peer(input coord_t c);
    return int'(c.y)*3+int'(c.x);
  endfunction
  function automatic head_flit_t extend(input head_flit_t h);
    head_flit_t v; v=h; v.length=h.length+5; return v;
  endfunction
  assign freshness={16'b0,epoch_q,seq_q};
  // R6.6 transcript words 0-5: HEAD(wire) || VC || ver || epoch || seq; words 6.. are the payload
  assign tx_hdr={64'b0,seq_q,epoch_q,8'd1,8'(message_to_vc(msg_q)),32'(extend(head_q))};
  assign tx_req=ts==T_REQ;
  assign tx_wd=e_widx<6 ? tx_hdr[3'(e_widx)*32+:32] : tp[4'(e_widx-5'd6)];
  assign tx_mlen=7'(24+4*pn);
  assign tx_ready=(ts==T_IDLE) && !ni_tb && tx_msg_type<=MSG_ATTEST_REVOKE && tx_dest_coord.x<3 && tx_dest_coord.y<2 &&
                  (!is_control(tx_msg_type) || (peer(tx_dest_coord)==PEER && tx_seq!=64'hffffffffffffffff));
  assign tx_payload_ready=ts==T_FILL;
  // control traffic exists only between TILE and PEER (R7.1): any other control destination is refused
  assign tx_error=ni_error || (tx_valid && ts==T_IDLE && is_control(tx_msg_type) && peer(tx_dest_coord)!=PEER);
  assign tx_busy=ts!=T_IDLE || ni_tb;
  assign ni_tv=ts==T_ISSUE && preview==head_q;
  assign ni_pv=ts==T_NIFILL;
  // Valid/ready paths are single-assignment continuous logic (S1 fix, run 2026-10-21 probe: a default-then-override
  // always_comb that read the NI's ready and wrote its valid/flit oscillated in zero time with the NI's own logic).
  // No block both reads a ready and writes the matching valid/flit; flits are built by mkflit (no transient values).
  function automatic flit_t mkflit(input logic [31:0] d, input flit_type_e ty, input logic [1:0] vc);
    flit_t f; f.flit_data=d; f.flit_type=ty; f.vc_id=vc; return f;
  endfunction
  function automatic logic [31:0] len_adj(input logic [31:0] hd, input int delta);
    head_flit_t h; h=head_flit_t'(hd); h.length=5'(int'(h.length)+delta); return 32'(h);
  endfunction
  assign noc_tx_valid = extension!=0 ? 1'b1 : ni_nv;
  assign noc_tx_flit  = extension!=0 ? mkflit(freshness[(extension-1)*32+:32],FLIT_BODY,2'(message_to_vc(msg_q))) :
                        (ni_nf.flit_type==FLIT_HEAD && is_control(msg_q)) ? mkflit(len_adj(ni_nf.flit_data,5),ni_nf.flit_type,ni_nf.vc_id) :
                        ni_nf;
  assign ni_nr        = extension==0 && noc_tx_ready;
  always_ff @(posedge clk) if(ts==T_FILL && tx_payload_valid) tp[fill]<=tx_payload_data;
  always_ff @(posedge clk) begin
    if(rst) begin
      ts<=T_IDLE; pn<=0; fill<=0; send_fill<=0; extension<=0;
      seq_q<=0; epoch_q<=0; dest_q<='0; msg_q<=MSG_ATTEST_GRANT; ctl_q<=0;
      head_q<='0; tx_tag_q<=0; tx_seq<=0;
    end else begin
      if(extension!=0 && noc_tx_valid && noc_tx_ready)
        extension<=extension==5?0:extension+1;
      else if(extension==0 && ni_nv && ni_nr && ni_nf.flit_type==FLIT_HEAD && is_control(msg_q)) extension<=1;
      case(ts)
        T_IDLE: if(tx_valid && tx_ready) begin
          dest_q<=tx_dest_coord; msg_q<=tx_msg_type; ctl_q<=tx_control;
          pn<=message_payload_flits(tx_msg_type); fill<=0;
          seq_q<=tx_seq+1; epoch_q<=boot_epoch;
          ts<=message_payload_flits(tx_msg_type)==0?T_PREP:T_FILL;
        end
        T_FILL: if(tx_payload_valid) begin
          if(fill+1==pn) ts<=T_PREP; else fill<=fill+1;
        end
        T_PREP: begin
          head_q<=preview; ts<=is_control(msg_q)?T_REQ:T_ISSUE;
        end
        T_REQ: if(e_grant && e_grant_id==2'(TX_RID)) ts<=T_WAIT;
        T_WAIT: if(e_done && e_owner==2'(TX_RID)) begin tx_tag_q<=e_tag; ts<=T_ISSUE; end
        T_ISSUE: if(preview!=head_q) ts<=T_PREP;
          else if(ni_tr) begin
            if(is_control(msg_q)) tx_seq<=seq_q;
            send_fill<=0;
            ts<=pn==0?T_SEND:T_NIFILL;
          end
        T_NIFILL: if(ni_pr) begin
          if(send_fill+1==pn) ts<=T_SEND; else send_fill<=send_fill+1;
        end
        T_SEND: if(!ni_tb && !ni_nv && extension==0) ts<=T_IDLE;
        default: ts<=T_IDLE;
      endcase
    end
  end

  // ---------------- RX: input steering (one packet at a time on the link) + slot P verification
  typedef enum logic [2:0] {I_IDLE,I_PASS,I_PCOL,I_GCOL,I_DROP} is_t;
  typedef enum logic [2:0] {P_FREE,P_COL,P_PREP,P_REQ,P_WAIT,P_RDY,P_PLAY} ps_t;
  is_t is_q;
  ps_t ps;
  flit_t pb[32];                       // slot P flit store, LUTRAM (written only while collecting)
  flit_t ph;                           // slot P HEAD flit
  head_flit_t rh,in_h,gh;
  logic [5:0] rn,rc,play,gn,gc;
  logic frame_bad,g_frame_bad;
  logic [127:0] tag_q;                 // T1: MAC words captured during collect
  logic [159:0] rfresh;                // T4: F0-F4 captured during collect
  logic [15:0] g_pad;                  // slot G: F4[31:16] (padding check of the header pre-check)
  logic [1:0] g_vc;
  logic [3:0] d_reason;
  logic [5:0] rl[6];                   // rate limit: cycles until source s may be admitted to slot G again
  logic [255:0] rx_hdr;
  logic [4:0] praddr;
  flit_t pb_rd;
  flit_t ni_rf;
  logic ni_rv,ni_rr;
  logic in_head,in_term,in_ctl,in_src_ok,h_peer,to_p,p_hold,play_start,pass_now;
  logic [15:0] hold_run;
  int in_src;
  assign rh=head_flit_t'(ph.flit_data);
  assign in_h=head_flit_t'(noc_rx_flit.flit_data);
  assign in_head=noc_rx_flit.flit_type==FLIT_HEAD || noc_rx_flit.flit_type==FLIT_HEAD_TAIL;
  assign in_term=noc_rx_flit.flit_type==FLIT_TAIL || noc_rx_flit.flit_type==FLIT_HEAD_TAIL;
  assign in_ctl=is_control(in_h.msg_type);
  assign in_src_ok=in_h.src_x<3 && in_h.src_y<2;
  assign in_src=int'(in_h.src_y)*3+int'(in_h.src_x);
  assign h_peer=in_src_ok && in_src==PEER;
  assign to_p = h_peer;                // SF-1 steering on the stamped source (trusted after the ingress check)
  assign p_hold = is_q==I_IDLE && noc_rx_valid && in_head && in_ctl && to_p && ps!=P_FREE;   // D2: hold, never drop
  assign play_start=ps==P_RDY && is_q!=I_PASS;
  assign pass_now=is_q==I_IDLE && noc_rx_valid && in_head && !in_ctl && ps!=P_PLAY && !play_start;
  assign rx_hdr={64'b0,rfresh[63:0],rfresh[143:64],8'd1,8'(ph.vc_id),ph.flit_data};
  assign praddr=ps==P_PLAY ? play[4:0] : e_widx;
  assign pb_rd=pb[praddr];
  assign rx_req=ps==P_REQ;
  assign rx_wd=e_widx<6 ? rx_hdr[3'(e_widx)*32+:32] : pb_rd.flit_data;
  assign rx_mlen=7'(24+4*message_payload_flits(rh.msg_type));
  assign rx_busy=is_q!=I_IDLE || ps!=P_FREE || ni_rb;
  logic rx_pass_sel;
  assign rx_pass_sel  = is_q==I_PASS || pass_now;
  assign ni_rv        = rx_pass_sel ? noc_rx_valid : ps==P_PLAY;
  assign ni_rf        = rx_pass_sel ? noc_rx_flit : (play==0 ? mkflit(len_adj(ph.flit_data,-5),ph.flit_type,ph.vc_id) : pb_rd);
  assign noc_rx_ready = rx_pass_sel ? ni_rr : !((is_q==I_IDLE && noc_rx_valid && in_head && !in_ctl) || p_hold);   // held during a replay / D2
  // header pre-check (R6.7.4), shared form for slot P (rh, rn, frame_bad, rfresh) and slot G (gh, gn, g_frame_bad)
  function automatic logic hdr_bad(input head_flit_t h, input logic [1:0] vc, input logic [5:0] n, input logic fb, input logic [15:0] pad);
    return fb || h.msg_type>MSG_ATTEST_REVOKE || h.src_x>=3 || h.src_y>=2 || h.dest_x>=3 || h.dest_y>=2 ||
           peer(coord_t'({h.dest_x,h.dest_y}))!=TILE || vc!=message_to_vc(h.msg_type) ||
           n!=p7_length(h.msg_type)+5 || pad!=0;
  endfunction
  always_ff @(posedge clk) if(is_q==I_PCOL && noc_rx_valid && rc<MAX_WIRE) pb[rc[4:0]]<=noc_rx_flit;
  always_ff @(posedge clk) begin
    if(rst) begin
      is_q<=I_IDLE; ps<=P_FREE; rc<=0; rn<=0; play<=0; frame_bad<=0; gc<=0; gn<=0; g_frame_bad<=0; g_pad<=0; g_vc<=0;
      gh<='0; ph<='0; d_reason<=0; rfresh<=0;
      rejected_count<=0; accepted_count<=0; p_slot_drops<=0; reject_reason<=0;
      peer_accepted<=0; peer_replayed<=0; peer_rejected<=0; peer_hold_max<=0; hold_run<=0;
      tag_q<=0; rx_seq<=0;
      for(int s=0;s<6;s++) rl[s]<=0;
    end else begin
      logic ev_in,ev_p; logic [3:0] r_in,r_p;
      ev_in=0; r_in=0; ev_p=0; r_p=0;
      for(int s=0;s<6;s++) if(rl[s]!=0) rl[s]<=rl[s]-1;
      // ---- input steering
      case(is_q)
        I_IDLE: if(noc_rx_valid && noc_rx_ready) begin
          if(!in_head) begin ev_in=1; r_in=1; end                       // stray body/tail
          else if(!in_ctl) begin if(!in_term) is_q<=I_PASS; end          // data plane: plain pass-through
          else if(noc_rx_flit.flit_type==FLIT_HEAD_TAIL) begin ev_in=1; r_in=1; end
          else if(to_p) begin
            if(ps!=P_FREE) begin d_reason<=7; is_q<=I_DROP; end   // unreachable while p_hold holds the HEAD (D2)
            else if(in_h.length<10 || in_h.length>MAX_WIRE) begin d_reason<=1; is_q<=I_DROP; end
            else begin ph<=noc_rx_flit; rc<=1; rn<=6'(in_h.length); frame_bad<=0; ps<=P_COL; is_q<=I_PCOL; peer_accepted<=peer_accepted+1; end
          end else begin
            if(in_src_ok && rl[in_src]!=0) begin d_reason<=6; is_q<=I_DROP; end
            else begin
              if(in_src_ok) rl[in_src]<=6'(T_RL-1);
              if(in_h.length<10 || in_h.length>MAX_WIRE) begin d_reason<=1; is_q<=I_DROP; end
              else begin gh<=in_h; g_vc<=noc_rx_flit.vc_id; gc<=1; gn<=6'(in_h.length); g_frame_bad<=0; g_pad<=0; is_q<=I_GCOL; end
            end
          end
        end
        I_PASS: if(noc_rx_valid && noc_rx_ready && in_term) is_q<=I_IDLE;
        I_PCOL: if(noc_rx_valid) begin
          for(int k=0;k<5;k++) if(rc==6'(k+1)) rfresh[k*32+:32]<=noc_rx_flit.flit_data;                // T4
          for(int k=0;k<4;k++) if(rc==rn-6'd4+6'(k)) tag_q[k*32+:32]<=noc_rx_flit.flit_data;     // T1
          if(noc_rx_flit.vc_id!=ph.vc_id ||
             (rc+1==rn ? noc_rx_flit.flit_type!=FLIT_TAIL : noc_rx_flit.flit_type!=FLIT_BODY)) frame_bad<=1;
          if(in_term) begin
            is_q<=I_IDLE;
            if(rc+1!=rn || rc>=MAX_WIRE) begin ev_in=1; r_in=1; ps<=P_FREE; peer_rejected<=peer_rejected+1; end
            else ps<=P_PREP;
          end else if(rc>=MAX_WIRE-1) begin d_reason<=1; is_q<=I_DROP; ps<=P_FREE; peer_rejected<=peer_rejected+1; end
          else rc<=rc+1;
        end
        I_GCOL: if(noc_rx_valid) begin
          if(gc==5) g_pad<=noc_rx_flit.flit_data[31:16];
          if(noc_rx_flit.vc_id!=g_vc ||
             (gc+1==gn ? noc_rx_flit.flit_type!=FLIT_TAIL : noc_rx_flit.flit_type!=FLIT_BODY)) g_frame_bad<=1;
          if(in_term) begin
            is_q<=I_IDLE; ev_in=1;
            if(gc+1!=gn || gc>=MAX_WIRE) r_in=1;
            else r_in=hdr_bad(gh,g_vc,gn,g_frame_bad || noc_rx_flit.vc_id!=g_vc || noc_rx_flit.flit_type!=FLIT_TAIL,g_pad) ? 4'd1 : 4'd5;
          end else if(gc>=MAX_WIRE-1) begin d_reason<=1; is_q<=I_DROP; end
          else gc<=gc+1;
        end
        I_DROP: if(noc_rx_valid && in_term) begin
          is_q<=I_IDLE; ev_in=1; r_in=d_reason;
          if(d_reason==7) p_slot_drops<=p_slot_drops+1;
        end
        default: is_q<=I_IDLE;
      endcase
      // ---- slot P verification: framing -> header pre-check -> MAC -> epoch -> sequence, then replay
      case(ps)
        P_PREP: if(hdr_bad(rh,ph.vc_id,rn,frame_bad,rfresh[159:144])) begin ev_p=1; r_p=1; ps<=P_FREE; end
                else ps<=P_REQ;
        P_REQ: if(e_grant && e_grant_id==2'(RX_RID)) ps<=P_WAIT;
        P_WAIT: if(e_done && e_owner==2'(RX_RID)) begin
          if(!BYPASS_MAC && e_tag!=tag_q) begin ev_p=1; r_p=2; ps<=P_FREE; end
          else if(!BYPASS_EPOCH && rfresh[143:64]!=boot_epoch) begin ev_p=1; r_p=3; ps<=P_FREE; end
          else if(!BYPASS_SEQUENCE && (rfresh[63:0]==0 || rfresh[63:0]<=rx_seq)) begin ev_p=1; r_p=4; ps<=P_FREE; end
          else begin rx_seq<=rfresh[63:0]; accepted_count<=accepted_count+1; play<=0; ps<=P_RDY; end
        end
        P_RDY: if(play_start) ps<=P_PLAY;
        P_PLAY: if(ni_rr) begin
          if(play+1==rn) begin ps<=P_FREE; peer_replayed<=peer_replayed+1; end
          else play<=play==0?6:play+1;
        end
        default: ;
      endcase
      if(ev_p) peer_rejected<=peer_rejected+1;   // slot-P verdicts are peer packets (pre-check, MAC, epoch, sequence)
      if(p_hold) begin hold_run<=hold_run+16'd1; if(hold_run+16'd1>peer_hold_max) peer_hold_max<=hold_run+16'd1; end else hold_run<=0;
      if(ev_in || ev_p) begin
        rejected_count<=rejected_count+32'(ev_in)+32'(ev_p);
        reject_reason<=ev_p ? r_p : r_in;
      end
    end
  end
  // I-9: the NI error outputs end on local scalars (pure wiring, removed in synthesis). Left unconnected, XSim evaluated
  // the NI-scope concurrent check p_no_deliver_and_drop inconsistently on a rejected HEAD (reports/S1_NOTES_20261021.md
  // sec. 5a, same remedy as the plain NIs); its clocked twin is unchanged.
  logic ni_rpe,ni_rle,ni_rhv,ni_rpv;
  assign rx_head_valid=ni_rhv; assign rx_payload_valid=ni_rpv;
  noc_network_interface_p7 #(.CONTROL_ALLOWED(1'b1),.LOCAL_TILE_ID(TILE),.WD_LIMIT(64),.NI_SLOT_TIMEOUT(NI_SLOT_TIMEOUT)) ni(
    .clk,.rst,.tx_valid(ni_tv),.tx_ready(ni_tr),.tx_auth_preview(preview),
    .tx_dest_coord(dest_q),.tx_msg_type(msg_q),.tx_control(ctl_q),
    .tx_payload_data(tp[send_fill[3:0]]),.tx_payload_valid(ni_pv),.tx_payload_ready(ni_pr),
    .tx_mac_tag(tx_tag_q),.tx_error(ni_error),
    .noc_tx_flit(ni_nf),.noc_tx_valid(ni_nv),.noc_tx_ready(ni_nr),
    .noc_rx_flit(ni_rf),.noc_rx_valid(ni_rv),.noc_rx_ready(ni_rr),
    .rx_src_coord,.rx_dest_coord,.rx_msg_type,.rx_control,.rx_length,.rx_head_valid(ni_rhv),
    .rx_payload_data,.rx_payload_valid(ni_rpv),.rx_payload_last,.rx_ready,.rx_abort,
    .rx_mac_tag(),.rx_mac_valid(),.rx_protocol_error(ni_rpe),.rx_length_error(ni_rle),
    .ni_status_clr(1'b0),.ni_contain_sticky(),.ni_contain_cnt(),.ni_contain_info(),
    .ni_framing_sticky(),.ni_framing_cnt(),.tx_busy(ni_tb),.rx_busy(ni_rb));
  // synthesis translate_off
  localparam int H_MAX=512;
  always_ff @(posedge clk) if(!rst) begin
    if(p_hold && hold_run+16'd1>16'(H_MAX)) $error("noc_l2_auth_p7: D2 hold of %0d cycles exceeds H_MAX %0d at tile %0d", hold_run+16'd1, H_MAX, TILE);
    if(!rx_ready) $error("noc_l2_auth_p7: control consumer not ready at tile %0d (R7.7b requires an always-ready consumer)", TILE);
  end
  always_ff @(posedge clk) if(!rst && is_q==I_IDLE && noc_rx_valid && noc_rx_ready && in_head && in_ctl && to_p && ps!=P_FREE)
    $error("noc_l2_auth_p7: D2 violated, tile %0d dropped a peer packet for occupancy", TILE);
  // synthesis translate_on
  initial begin
    if(!MAC_ENABLE || !(TILE==3 || TILE==4) || !(PEER==3 || PEER==4) || PEER==TILE)
      $fatal(1,"noc_l2_auth_p7 requires MAC-on (PQ_MAC_ON) and TILE/PEER = 3/4");
  end
endmodule
